package com.hbm.client.arcwelder;
import com.hbm.machine.arcwelder.*;import java.util.*;import me.shedaniel.math.*;import me.shedaniel.rei.api.client.gui.Renderer;import me.shedaniel.rei.api.client.gui.widgets.*;import me.shedaniel.rei.api.client.plugins.REIClientPlugin;import me.shedaniel.rei.api.client.registry.category.CategoryRegistry;import me.shedaniel.rei.api.client.registry.display.*;import me.shedaniel.rei.api.common.category.CategoryIdentifier;import me.shedaniel.rei.api.common.display.basic.BasicDisplay;import me.shedaniel.rei.api.common.entry.*;import me.shedaniel.rei.api.common.util.EntryStacks;import me.shedaniel.rei.forge.REIPluginClient;import net.minecraft.network.chat.Component;
@REIPluginClient public final class ArcWelderReiPlugin implements REIClientPlugin {
 static final CategoryIdentifier<Display> TYPE=CategoryIdentifier.of("hbm","arcwelder");@Override public void registerCategories(CategoryRegistry event){event.add(new Category());event.addWorkstations(TYPE,EntryStacks.of(ArcWelderContent.ITEM.get()));}@Override public void registerScreens(me.shedaniel.rei.api.client.registry.screen.ScreenRegistry event){event.registerContainerClickArea(new Rectangle(67,26,32,14),ArcWelderScreen.class,TYPE);}@Override public void registerDisplays(DisplayRegistry event){for(var recipe:ArcWelderRecipes.recipes(event.getRecipeManager()))event.add(new Display(recipe));}
 static final class Display extends BasicDisplay{final ArcWelderRecipe recipe;Display(ArcWelderRecipe recipe){super(ArcWelderViews.inputs(recipe).stream().map(items->EntryIngredient.of(items.stream().map(EntryStacks::of).toList())).toList(),List.of(EntryIngredient.of(EntryStacks.of(recipe.output()))));this.recipe=recipe;}@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}}
 static final class Category implements DisplayCategory<Display>{@Override public CategoryIdentifier<Display> getCategoryIdentifier(){return TYPE;}@Override public Component getTitle(){return Component.translatable("jei.hbm.arcwelder");}@Override public Renderer getIcon(){return EntryStacks.of(ArcWelderContent.ITEM.get());}@Override public int getDisplayWidth(Display display){return 166;}@Override public int getDisplayHeight(){return 65;}@Override public List<Widget> setupDisplay(Display display,Rectangle bounds){var widgets=new ArrayList<Widget>();widgets.add(Widgets.createDrawableWidget((g,x,y,partial)->ArcWelderViews.draw(display.recipe,g,bounds.x,bounds.y)));var positions=ArcWelderViews.positions(display.recipe);for(int i=0;i<display.getInputEntries().size();i++)widgets.add(Widgets.createSlot(new Point(bounds.x+positions[i][0],bounds.y+positions[i][1])).entries(display.getInputEntries().get(i)).disableBackground().markInput());widgets.add(Widgets.createSlot(new Point(bounds.x+102,bounds.y+24)).entries(display.getOutputEntries().getFirst()).disableBackground().markOutput());widgets.add(Widgets.createSlot(new Point(bounds.x+75,bounds.y+31)).entries(List.of(EntryStacks.of(ArcWelderContent.ITEM.get()))).disableBackground());return widgets;}}
}
